function drawGradient() {
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c1 = color("#aaeaff");
    let c2 = color("#e9f8ff");
    let c3 = color("#fff5b6");

    let c = t < 0.5
      ? lerpColor(c1, c2, t * 2)
      : lerpColor(c2, c3, (t - 0.5) * 2);

    stroke(c);
    line(0, y, width, y);
  }
}

function drawWindGlyph(x, y, s, lineS) {
  this.x = x;
  this.y = y;
  this.animation = 0;
  this.speed = random(0.5, 5);
  this.col = random(COLORS);
  this.alpha = 255;//random(120, 255);

  this.hiting = 0;
  this.draw = function() {  
    push();

    stroke(this.col + hex(floor(this.alpha), 2));
    translate(this.x+this.hiting, this.y);
    var ratio = (this.animation - lineS) / s;

    // 横線
    if(this.animation < lineS){
     line(-lineS, 0, -lineS+this.animation, 0);
    }else if(ratio < 1){
      line(-lineS, 0, 0, 0);
      if(this.animation > lineS + s * 0.2){
        arc(0, -s*0.5,s,s,HALF_PI+(-PI*1.7)*ratio, HALF_PI);
        arc(0, -s*0.5,s*0.5,s*0.5,HALF_PI+ (-PI*1.3)*ratio, HALF_PI);
      }
    }else{
      line(-lineS, 0, 0, 0);
      arc(0, -s*0.5,s,s,HALF_PI+(-PI*1.7), HALF_PI);
      translate(0, -s*0.5);
      rotate(-(this.animation -lineS-s)* 0.05);
      arc(0, 0,s*0.5,s*0.5,HALF_PI+ (-PI*1.3), HALF_PI);
    }

    pop();

    this.animation += this.speed;
  }

  this.hit = function(y) {
    if(abs(this.y - y) < 20){
      this.hiting ++;
    }else{
      this.hiting = 0;
    }
  }
}

